INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn06-s2', 'listen-06', 2, 'choice', '听录音，根据录音中的内容，将正确答案填在括号中。背景：小林来到 HKK 株式会社的员工宿舍，管理员向他介绍宿舍的情况。', 132228, 180863, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn06-s2-q1', 'lsn06-s2', 1, '社員寮にはWi-Fiがありますか。', '[{"key":"a","text":"はい、あります。"},{"key":"b","text":"いいえ、ありません。"}]'::jsonb, 'b');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn06-s2-q2', 'lsn06-s2', 2, '食堂は社員寮の＿＿階です。', '[{"key":"a","text":"1"},{"key":"b","text":"2"},{"key":"c","text":"3"}]'::jsonb, 'c');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn06-s2-q3', 'lsn06-s2', 3, '小林さんの部屋には洗濯機がありますか。', '[{"key":"a","text":"はい、あります。"},{"key":"b","text":"いいえ、ありません。"}]'::jsonb, 'b');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn06-s2-q4', 'lsn06-s2', 4, '自動販売機は社員寮の＿＿階です。', '[{"key":"a","text":"1"},{"key":"b","text":"2"},{"key":"c","text":"3"}]'::jsonb, 'b');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l1', 'lsn06-s2', 1, '管理員', 132528, 141833, 'ここはHKK株式会社の社員寮です。', '管理员：这里是 HKK 株式会社的员工宿舍。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l2', 'lsn06-s2', 2, '小林', 142926, 147811, 'こんにちは。新入社員の小林です。', '小林：您好。我是新员工小林。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l3', 'lsn06-s2', 3, '管理員', 147812, 153605, '小林さんですか。小林さんの部屋は５階です。こちらは部屋の鍵です。', '管理员：是小林啊。你的房间在5楼，这是房间钥匙。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l4', 'lsn06-s2', 4, '小林', 154554, 155694, 'ありがとうございます。', '小林：谢谢。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l5', 'lsn06-s2', 5, '管理員', 156489, 159219, '３階には食堂と会議室があります。', '管理员：3楼有食堂和会议室。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l6', 'lsn06-s2', 6, '小林', 159220, 164621, 'わかりました。あのう、Wi-Fiはありますか。', '小林：明白了。请问有 Wi-Fi 吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l7', 'lsn06-s2', 7, '管理員', 164622, 169237, 'すみません。ここにはWi-Fiはありません。', '管理员：不好意思，这里没有 Wi-Fi。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l8', 'lsn06-s2', 8, '小林', 169357, 173030, 'そうですか。じゃ、洗濯機はありますか。', '小林：这样啊。那有洗衣机吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l9', 'lsn06-s2', 9, '管理員', 173481, 176247, 'あります。２階にあります。それから、自動販売機も２階です。', '管理员：有，在2楼。另外自动售货机也在2楼。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn06-s2-l10', 'lsn06-s2', 10, '小林', 176960, 180163, 'わかりました。どうぞ、よろしくお願いします。', '小林：明白了。请多关照。');
